    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var status = GetStepStatus(step);
            <li class="step-item @status" @onclick="() => HandleClick(step)" role="button" tabindex="0">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@StepNames[i]</span>
            </li>
        }
