    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" rows="12" maxlength="@MaxLength" @bind="CoverLetter" @bind:event="oninput" placeholder="Tell us why you're a great fit for this role..."></textarea>
        <div class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
