@page "/apply"
@using sv_7261a3be3ee3438281cd24c48bb8685f.Components.Pages.Apply
@using sv_7261a3be3ee3438281cd24c48bb8685f.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 2:
            <WorkHistoryStep Entries="workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
            break;
        case 3:
            <ReferencesStep References="references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 4:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 5:
            <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                        OnEdit="GoToStep" OnBack="GoBack" OnSubmit="HandleSubmit"
                        IsSubmitting="isSubmitting" IsSubmitted="isSubmitted" ApplicationId="applicationId" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();

    // Step 1
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new() { new() };

    // Step 3
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4
    private string coverLetter = "";

    // Submission
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(4);
        currentStep = 5;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        try
        {
            var app = new Models.JobApplication(
                new Models.PersonalInfo(fullName, email, phone, address),
                new Models.WorkHistory(workEntries.Select(e => new Models.WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Models.Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(app);
            applicationId = id;
            isSubmitted = true;
            completedSteps.Add(5);
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 1)
            currentStep--;
    }
}

