.work-entry,
.reference-entry {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    position: relative;
}

.work-entry legend,
.reference-entry legend {
    font-weight: 600;
    color: #374151;
    padding: 0 0.5rem;
}

.remove-btn {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
}

