    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.375rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.875rem;
}

.review-section dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.date-range {
    color: #6b7280;
    font-size: 0.8125rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.875rem;
    color: #374151;
    margin: 0;
}

